/**
 * AutoRemediate - Attempts automatic remediation for common alarm conditions.
 * Called by the event processing policy when specific alarms fire.
 *
 * Parameters:
 *   $1 - alarm ID
 *   $2 - remediation action: 'restart-agent', 'clear-cache', 'notify-only'
 */

local node = $node;
local alarmId = $1;
local action = ($2 != null) ? $2 : 'notify-only';

local log = CreateArray();
log->append('AutoRemediate started for node: ' + node.name);
log->append('Alarm ID: ' + alarmId);
log->append('Action: ' + action);

if (action == 'restart-agent' && node.isAgent)
{
  log->append('Sending agent restart command...');
  AgentExecuteAction(node, 'Agent.Restart', null);
  log->append('Agent restart command sent.');
}
else if (action == 'clear-cache')
{
  log->append('Cache clear not yet implemented.');
}
else
{
  log->append('No automated action taken - notification only.');
}

log->append('AutoRemediate completed.');
return ArrayToString(log, '\n');
